564:     delete PRIVATE(this)->sorendermanager;
565:     PRIVATE(this)->initialsorendermanager = false;
566:   }
567:   PRIVATE(this)->sorendermanager = manager;
568:   if (carrydata) {
569:     PRIVATE(this)->sorendermanager->setSceneGraph(scene);
570:     PRIVATE(this)->sorendermanager->setCamera(camera);
571:     PRIVATE(this)->sorendermanager->setViewportRegion(vp);
572:   }
573: 
574:   if (scene) scene->unref();
575:   if (camera) camera->unref();
