698:   }
699:   if(win) {
700:     dev_pix_ratio = win->devicePixelRatio();
701:   }
702:   else {
703:     dev_pix_ratio = ((QGuiApplication*)QGuiApplication::instance())->devicePixelRatio();
704:   }
705:   if(PRIVATE(this)->device_pixel_ratio != dev_pix_ratio) {
706:     PRIVATE(this)->device_pixel_ratio = dev_pix_ratio;
707:     emit devicePixelRatioChanged(dev_pix_ratio);
708:     return true;
709:   }
710: #endif
711:   return false;
712: }
