1022: void
1023: QuarterWidget::setNavigationModeFile(const QUrl & url)
1024: {
1025:   QString filename;
1026: 
1027:   if (url.scheme()=="coin") {
1028:     filename = url.path();
1029:     //FIXME: This conditional needs to be implemented when the
1030:     //CoinResources systems if working
1031: #if 0
1032:     //#if (COIN_MAJOR_VERSION==3) && (COIN_MINOR_VERSION==0)
1033: #endif
1034:     //Workaround for differences between url scheme, and Coin internal
1035:     //scheme in Coin 3.0.
1036:     if (filename[0]=='/') {
1037:       filename.remove(0,1);
1038:     }
1039: #if 0
1040:     //#endif
1041: #endif
1042:     filename = url.scheme()+':'+filename;
1043:   }
1044:   else if (url.scheme()=="file")
1045:     filename = url.toLocalFile();
1046:   else if (url.isEmpty()) {
1047:     if (PRIVATE(this)->currentStateMachine) {
1048:       this->removeStateMachine(PRIVATE(this)->currentStateMachine);
1049:       delete PRIVATE(this)->currentStateMachine;
1050:       PRIVATE(this)->currentStateMachine = NULL;
1051:       PRIVATE(this)->navigationModeFile = url;
1052:     }
1053:     return;
1054:   }
1055:   else {
1056:     qDebug()<<url.scheme()<<"is not recognized";
1057:     return;
1058:   }
1059: 
1060:   QByteArray filenametmp = filename.toLocal8Bit();
1061:   ScXMLStateMachine * stateMachine = NULL;
1062: 
1063:   if (filenametmp.startsWith("coin:")){
1064:     stateMachine = ScXML::readFile(filenametmp.data());
1065:   }
1066:   else {
1067:     //Use Qt to read the file in case it is a Qt resource
1068:     QFile file(filenametmp);
1069:     if (file.open(QIODevice::ReadOnly)){
1070:       QByteArray fileContents = file.readAll();
1071:       stateMachine = ScXML::readBuffer(SbByteBuffer(fileContents.size(), fileContents.constData()));
1072:       file.close();
1073:     }
1074:   }
1075: 
1076:   if (stateMachine &&
1077:       stateMachine->isOfType(SoScXMLStateMachine::getClassTypeId())) {
1078:     SoScXMLStateMachine * newsm = 
1079:       static_cast<SoScXMLStateMachine *>(stateMachine);
1080:     if (PRIVATE(this)->currentStateMachine) {
1081:       this->removeStateMachine(PRIVATE(this)->currentStateMachine);
1082:       delete PRIVATE(this)->currentStateMachine;
1083:     }
1084:     this->addStateMachine(newsm);
1085:     newsm->initialize();
1086:     PRIVATE(this)->currentStateMachine = newsm;
1087:   }
1088:   else {
1089:     delete stateMachine;
1090: 	stateMachine = NULL;
1091:     qDebug()<<filename;
1092:     qDebug()<<"Unable to load"<<url;
1093:     return;
1094:   }
1095: 
1096:   //If we have gotten this far, we have successfully loaded the
1097:   //navigation file, so we set the property
1098:   PRIVATE(this)->navigationModeFile = url;
1099: 
1100:   if (QUrl(DEFAULT_NAVIGATIONFILE) == PRIVATE(this)->navigationModeFile ) {
1101: 
1102:     // set up default cursors for the examiner navigation states
1103:     //FIXME: It may be overly restrictive to not do this for arbitrary
1104:     //navigation systems? - BFG 20090117
1105:     setupDefaultCursors();
